def find_first_occurrence(arr, num):
    # Since the array is sorted, we can use binary search to efficiently find the first occurrence.
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == num:
            return mid  # Return the index as soon as we find the match
        elif arr[mid] < num:
            left = mid + 1
        else:
            right = mid - 1
    # If we reach this point, it means num was not in the array
    return -1

def sum_Of_Subarray_Prod(lst):
    """
    Calculates the sum of products of all possible sublists of a given list.
    """
    total_sum = 0
    n = len(lst)
    for i in range(n):
        for j in range(i, n):
            subarray_prod = 1
            for k in range(i, j + 1):
                subarray_prod *= lst[k]
            total_sum += subarray_prod
    return total_sum

