def check_min_heap(arr):
    # Check if the length of the array is less than or equal to 1
    # An empty array or a single-element array is always a min heap
    if len(arr) <= 1:
        return True
    # Loop through the array from the second element to the second last element
    for i in range(1, len(arr)):
        # If the left child is greater than the parent, return False
        if 2*i <= len(arr) and arr[2*i] > arr[i]:
            return False
        # If the right child is greater than the parent, return False
        if 2*i+1 <= len(arr) and arr[2*i+1] > arr[i]:
            return False
    return True

def jacobsthal_num(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        j_num = [0, 1]
        for i in range(2, n + 1):
            j_num.append(2 * j_num[i - 2] + j_num[i - 1])
        return j_num[n]

def jacobsthal_num(n):
    """Find the nth Jacobsthal number."""
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return jacobsthal_num(n - 1) + 2 * jacobsthal_num(n - 2)

def second_smallest(numbers):
    if len(numbers) < 2:
        return None

    smallest = float('inf')
    second_smallest = float('inf')

    for num in numbers:
        if num < smallest:
            second_smallest = smallest
            smallest = num
        elif smallest < num < second_smallest:
            second_smallest = num

    if second_smallest == float('inf'):
        return None

    return second_smallest

