def count_divisors(n: int) -> bool:
    """
    Returns True if the count of divisors of n is even, otherwise False.
    """
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            # i is a divisor
            if i * i == n:
                count += 1  # perfect square divisor counted once
            else:
                count += 2  # pair of divisors
        i += 1
    return count % 2 == 0

def mul_even_odd(nums):
    # Initialize product as 1 (neutral element for multiplication)
    product = 1
    for num in nums:
        # Check if the number is even
        if num % 2 == 0:
            # Multiply the current product by the even number
            product *= num
        else:
            # Multiply the current product by the next odd number
            product *= (num + 1)
    return product

def mul_even_odd(lst):
